          {filteredSkills.map((skill) => (
            <SkillCard
              key={skill.name}
              skill={skill}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />
          ))}
        </div>
      )}

      {/* Drawer */}
      {drawerOpen && drawerType === "skill" && <ProjectSkillDrawer />}
    </div>
  );
}

